  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/client\"\n}\n\ndatasource db {\n  provider  = \"postgresql\"\n  url       = env(\"DATABASE_URL\")\n  directUrl = env(\"DIRECT_URL\")\n}\n\nmodel Customer {\n  id                String    @id @default(uuid())\n  email             String    @unique\n  passwordHash      String\n  fullName          String\n  phoneNumber       String\n  isVerified        Boolean   @default(false)\n  verificationToken String?\n  avatarUrl         String?\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n  bookings          Booking[]\n  reviews           Review[]\n\n  @@map(\"customers\")\n}\n\nmodel AdminUser {\n  id           String             @id @default(uuid())\n  email        String             @unique\n  passwordHash String\n  fullName     String\n  role         String             @default(\"ADMIN\") // ADMIN, SUPERADMIN\n  createdAt    DateTime           @default(now())\n  updatedAt    DateTime           @updatedAt\n  auditLogs    SecurityAuditLog[]\n\n  @@map(\"admin_users\")\n}\n\nmodel PartnerProperty {\n  id                   String        @id @default(uuid())\n  kmPropertyId         String        @unique // External Reference ID di Kost Management\n  ownerName            String\n  ownerPhone           String\n  ownerWhatsapp        String\n  name                 String\n  slug                 String        @unique\n  address              String\n  city                 String\n  district             String\n  latitude             Float?\n  longitude            Float?\n  description          String?\n  genderType           String        @default(\"MIXED\")\n  generalFacilities    String // JSON Array: [\"Wi-Fi\", \"Parkir Mobil\"]\n  photos               String // JSON Array: URLs\n  termsAndRules        String?\n  requirementsSchema   String // JSON: standard_presets, custom_checkboxes, notes (ADR-009)\n  paymentBankName      String\n  paymentAccountNumber String\n  paymentAccountHolder String\n  paymentQrisUrl       String?\n  partnershipStatus    String        @default(\"WAITING_REVIEW\") // WAITING_REVIEW, ACTIVE, REJECTED, SUSPENDED, EXPIRED\n  rejectionReason      String?\n  avgRating            Float         @default(0.0)\n  totalReviews         Int           @default(0)\n  lastSyncedAt         DateTime? // ADR-005\n  createdAt            DateTime      @default(now())\n  updatedAt            DateTime      @updatedAt\n  rooms                PartnerRoom[]\n  bookings             Booking[]\n  reviews              Review[]\n\n  @@index([city])\n  @@index([partnershipStatus])\n  @@map(\"partner_properties\")\n}\n\nmodel PartnerRoom {\n  id                String          @id @default(uuid())\n  kmRoomId          String          @unique // External Reference ID di Kost Management\n  partnerPropertyId String\n  partnerProperty   PartnerProperty @relation(fields: [partnerPropertyId], references: [id], onDelete: Cascade)\n  roomNumber        String\n  roomType          String          @default(\"PRIVATE\") // PRIVATE, SHARED\n  sizeSqm           Float?\n  facilities        String // JSON Array: [\"AC\", \"Kamar Mandi Dalam\"]\n  photos            String // JSON Array: URLs\n  monthlyPrice      Float // Tarif per slot per bulan (ADR-004)\n  totalCapacity     Int // Total slot/orang (ADR-010)\n  occupiedSlots     Int             @default(0)\n  reservedSlots     Int             @default(0)\n  status            String          @default(\"AVAILABLE\") // AVAILABLE, MAINTENANCE\n  lastSyncedAt      DateTime?\n  createdAt         DateTime        @default(now())\n  updatedAt         DateTime        @updatedAt\n  bookings          Booking[]\n\n  @@index([partnerPropertyId])\n  @@map(\"partner_rooms\")\n}\n\nmodel Booking {\n  id                   String             @id @default(uuid())\n  bookingCode          String             @unique // Contoh: KA-202611-0089\n  customerId           String\n  customer             Customer           @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  partnerPropertyId    String\n  partnerProperty      PartnerProperty    @relation(fields: [partnerPropertyId], references: [id], onDelete: Cascade)\n  partnerRoomId        String\n  partnerRoom          PartnerRoom        @relation(fields: [partnerRoomId], references: [id], onDelete: Cascade)\n  slotsCount           Int\n  durationMonths       Int\n  startDate            DateTime\n  endDate              DateTime\n  pricePerSlot         Float\n  totalAmount          Float // ADR-004: pricePerSlot * slotsCount * durationMonths\n  occupantsData        String // JSON Array data seluruh penghuni\n  status               String             @default(\"PENDING_PAYMENT\") // PENDING_PAYMENT, PAYMENT_SUBMITTED, ACCEPTED, REJECTED, CHECKED_IN, CHECK_IN_OVERDUE, CANCELLED, EXPIRED, COMPLETED\n  cancellationReason   String?\n  paymentDeadline      DateTime // T + 60 menit (ADR-000)\n  verificationDeadline DateTime? // T + 24 jam (ADR-003)\n  checkInDeadline      DateTime? // T + 14 hari (ADR-000)\n  isNeedsAttention     Boolean            @default(false) // ADR-003: Flag SLA Overdue >24 jam\n  idempotencyKey       String             @unique // ADR-000\n  createdAt            DateTime           @default(now())\n  updatedAt            DateTime           @updatedAt\n  paymentSubmission    PaymentSubmission?\n  refundRequest        RefundRequest?\n  review               Review?\n\n  @@index([customerId])\n  @@index([partnerPropertyId])\n  @@index([status])\n  @@index([isNeedsAttention])\n  @@map(\"bookings\")\n}\n\nmodel PaymentSubmission {\n  id                  String   @id @default(uuid())\n  bookingId           String   @unique\n  booking             Booking  @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n  transferReceiptUrl  String\n  senderBankName      String?\n  senderAccountHolder String?\n  submissionNotes     String?\n  submittedAt         DateTime @default(now())\n  createdAt           DateTime @default(now())\n  updatedAt           DateTime @updatedAt\n\n  @@map(\"payment_submissions\")\n}\n\nmodel RefundRequest {\n  id               String    @id @default(uuid())\n  bookingId        String    @unique\n  booking          Booking   @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n  bankName         String\n  accountNumber    String\n  accountHolder    String\n  refundAmount     Float\n  penaltyDeduction Float     @default(0.0)\n  status           String    @default(\"PENDING\") // PENDING, COMPLETED\n  requestedAt      DateTime  @default(now())\n  completedAt      DateTime?\n  createdAt        DateTime  @default(now())\n  updatedAt        DateTime  @updatedAt\n\n  @@map(\"refund_requests\")\n}\n\nmodel Review {\n  id                String          @id @default(uuid())\n  bookingId         String          @unique // ADR-006: Maksimal 1 review per booking ID\n  booking           Booking         @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n  customerId        String\n  customer          Customer        @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  partnerPropertyId String\n  partnerProperty   PartnerProperty @relation(fields: [partnerPropertyId], references: [id], onDelete: Cascade)\n  rating            Int // 1 sampai 5\n  reviewText        String\n  isPublished       Boolean         @default(true)\n  createdAt         DateTime        @default(now())\n  updatedAt         DateTime        @updatedAt\n\n  @@index([customerId])\n  @@index([partnerPropertyId])\n  @@map(\"reviews\")\n}\n\nmodel SecurityAuditLog {\n  id           String    @id @default(uuid())\n  adminUserId  String\n  adminUser    AdminUser @relation(fields: [adminUserId], references: [id], onDelete: Cascade)\n  action       String // Contoh: 'VIEW_UNMASKED_CUSTOMER_ID'\n  resourceType String // 'BOOKING', 'CUSTOMER'\n  resourceId   String\n  reason       String\n  ipAddress    String\n  createdAt    DateTime  @default(now())\n\n  @@index([adminUserId])\n  @@map(\"security_audit_logs\")\n}\n",
